<?php
require_once __DIR__.'/../../auth/auth_check.php';
require_once __DIR__.'/../../config/database.php';
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  $nama=trim($_POST['nama_perusahaan']??'');$nomor=trim($_POST['nomor_permohonan']??'');
  if($nama===''||$nomor===''){$error='Nama perusahaan dan nomor permohonan wajib diisi.';}else{
    $stmt=$pdo->prepare('INSERT INTO lahan_kompensasi (nomor_permohonan,nama_perusahaan,lokasi_lahan,luas_lahan,provinsi,kabupaten,status_lahan,tanggal_pengajuan) VALUES (?,?,?,?,?,?,?,?)');
    $stmt->execute([$nomor,$nama,$_POST['lokasi_lahan']??'',(float)($_POST['luas_lahan']??0),$_POST['provinsi']??'',$_POST['kabupaten']??'',$_POST['status_lahan']??'Diajukan',$_POST['tanggal_pengajuan']??date('Y-m-d')]);
    $pdo->prepare('INSERT INTO aktivitas_log (user_id,aksi,entitas,entitas_id,detail) VALUES (?,?,?,?,?)')->execute([$_SESSION['user_id'],'Menambah','lahan_kompensasi',$pdo->lastInsertId(),'Data lahan kompensasi ditambahkan']);
    header('Location: index.php');exit;
  }
}
$rows=[];
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lahan Kompensasi | SICERDAS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><link href="../../assets/css/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/../../layouts/sidebar.php';?><div class="main-wrapper"><?php include __DIR__.'/../../layouts/navbar.php';?><main class="content"><div class="page-heading"><div><p>Manajemen Lahan</p><h1>Lahan Kompensasi</h1></div></div><div class="row g-3"><div class="col-lg-4"><div class="panel p-3"><h2 class="fs-6">Tambah Data</h2><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?>
<form method="post" class="vstack gap-2"><input class="form-control" name="nomor_permohonan" placeholder="Nomor permohonan" required><input class="form-control" name="nama_perusahaan" placeholder="Nama perusahaan" required><input class="form-control" name="lokasi_lahan" placeholder="Lokasi lahan"><input type="number" step="0.01" class="form-control" name="luas_lahan" placeholder="Luas (Ha)"><input class="form-control" name="provinsi" placeholder="Provinsi"><input class="form-control" name="kabupaten" placeholder="Kabupaten"><input type="date" class="form-control" name="tanggal_pengajuan" value="<?=date('Y-m-d')?>"><select class="form-select" name="status_lahan"><option>Diajukan</option><option>Diproses</option><option>Disetujui</option><option>Ditolak</option></select><button class="btn btn-orange">Simpan</button></form></div></div><div class="col-lg-8"><div class="panel table-panel"><div class="table-responsive"><table class="table sicerdas-table"><thead><tr><th>No.</th><th>Perusahaan</th><th>Lokasi</th><th>Luas</th><th>Provinsi</th><th>Status</th></tr></thead><tbody><?php $rows=$pdo->query('SELECT * FROM lahan_kompensasi ORDER BY created_at DESC')->fetchAll();foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['nomor_permohonan'])?></td><td><?=htmlspecialchars($r['nama_perusahaan'])?></td><td><?=htmlspecialchars($r['lokasi_lahan'])?></td><td><?=number_format((float)$r['luas_lahan'],2)?> Ha</td><td><?=htmlspecialchars($r['provinsi'])?></td><td><?=htmlspecialchars($r['status_lahan'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="6" class="text-center py-4">Belum ada data.</td></tr><?php endif;?></tbody></table></div></div></div></div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
